import{_ as a,o as n,c as t,a0 as l}from"./chunks/framework.DhQjJcnt.js";const g=JSON.parse('{"title":"Skill: /call-external","description":"","frontmatter":{},"headers":[],"relativePath":"references/skills/call-external.md","filePath":"references/skills/call-external.md"}'),i={name:"references/skills/call-external.md"};function o(c,e,r,h,s,d){return n(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="skill-call-external" tabindex="-1">Skill: <code>/call-external</code> <a class="header-anchor" href="#skill-call-external" aria-label="Permalink to &quot;Skill: `/call-external`&quot;">​</a></h1><h2 id="ten" tabindex="-1">Tên <a class="header-anchor" href="#ten" aria-label="Permalink to &quot;Tên&quot;">​</a></h2><p><code>call-external</code> (Đồng thời là Hashtag <code>#call-external</code>)</p><h2 id="cach-dung-command-trigger" tabindex="-1">Cách dùng (Command/Trigger) <a class="header-anchor" href="#cach-dung-command-trigger" aria-label="Permalink to &quot;Cách dùng (Command/Trigger)&quot;">​</a></h2><ul><li>KHÔNG gọi độc lập qua slash command, mà là một thẻ đánh dấu (Hashtag) lồng ghép bên trong các bước <code>/api-spec</code>, <code>/grill-api-spec</code> và sinh code <code>/api</code>.</li><li>Nếu Member gõ <code>/call-external &lt;API ID&gt;</code>, Agent sẽ tìm đúng file API đó và gắn thẻ này vào.</li></ul><h2 id="input-du-lieu-đau-vao" tabindex="-1">Input (Dữ liệu đầu vào) <a class="header-anchor" href="#input-du-lieu-đau-vao" aria-label="Permalink to &quot;Input (Dữ liệu đầu vào)&quot;">​</a></h2><ul><li>ID của Function hoặc đường dẫn API Endpoint (Ví dụ: <code>API-AUTH-001</code>, <code>stripe/charge</code>).</li></ul><h2 id="output-ket-qua-mong-đoi" tabindex="-1">Output (Kết quả mong đợi) <a class="header-anchor" href="#output-ket-qua-mong-đoi" aria-label="Permalink to &quot;Output (Kết quả mong đợi)&quot;">​</a></h2><ul><li>Tìm đến đúng file cấu hình kỹ thuật <code>api/&lt;seq&gt;/01-backend-spec.yaml</code> (hoặc <code>common/yaml</code>).</li><li>Bổ sung định nghĩa vào mảng <code>externalCalls</code> và gắn thêm hashtag <code>#call-external</code> vào trong file YAML.</li></ul><h2 id="description-y-nghia" tabindex="-1">Description / Ý nghĩa <a class="header-anchor" href="#description-y-nghia" aria-label="Permalink to &quot;Description / Ý nghĩa&quot;">​</a></h2><ul><li>Dành riêng cho việc đánh dấu các API có thực hiện <strong>Gọi ra bên ngoài hệ thống (Third-party integrations)</strong>.</li><li>Ví dụ: API Thanh toán có gọi sang Cổng Stripe, hoặc API Gửi Email có gọi sang SendGrid. Hành động này tiềm ẩn rủi ro về Network Timeout, Lỗi kết nối, do đó bắt buộc phải cắm cờ <code>#call-external</code>.</li><li>hệ thống bộ code Backend khi nhìn thấy cờ này sẽ tự động sinh code bổ sung thêm các cơ chế chịu lỗi (Fault tolerance) như Retry, Timeout, Circuit Breaker.</li></ul><h2 id="chu-y-quan-trong" tabindex="-1">Chú ý quan trọng <a class="header-anchor" href="#chu-y-quan-trong" aria-label="Permalink to &quot;Chú ý quan trọng&quot;">​</a></h2><ul><li><strong>Tuyệt đối cấm:</strong> Kỹ năng này chỉ được phép ghi thêm tag vào file <code>01-backend-spec.yaml</code>. Không được quyền can thiệp vào file <code>ir/design.yaml</code>, và tuyệt đối không xuất ra các file Markdown report giả mạo.</li></ul><hr><h2 id="example-prompt-mau-goi" tabindex="-1">Example prompt (mẫu gọi) <a class="header-anchor" href="#example-prompt-mau-goi" aria-label="Permalink to &quot;Example prompt (mẫu gọi)&quot;">​</a></h2><p><strong>Quy tắc:</strong> một session = một command · chat mới khi đổi phase · cập nhật <code>.harness/progress.md</code> nếu có.</p><p><strong>Khi nào:</strong> Gọi khi scope khớp mô tả skill ở trên.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/call-external</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Surface: {admin-web} · Module: {CMP-…} · Scope: {mô tả ngắn}</span></span></code></pre></div>',18)])])}const p=a(i,[["render",o]]);export{g as __pageData,p as default};
